 if p.package_state<>'draft' or p.clinic_id<>m.clinic_id or p.patient_id<>m.patient_id or p.consultation_id<>m.consultation_id or p.reconstruction_output_manifest_id<>m.reconstruction_output_manifest_id or p.model_artifact_id<>m.reconstruction_artifact_id or p.geometry_revision<>m.geometry_revision or p.normalization_version<>'graftvision-model-normalization-v1' or not graftvision_private.is_assigned_verified_doctor(p_session_id,p_provider_identity_id,p.consultation_id,'CONSULT-PERM-001') then raise exception using errcode='42501',message='MODEL_CURVE_DENIED'; end if;
 if p.revision<>p_expected_package_revision or p_curve_code not in ('current_hairline','proposed_hairline','frontal_boundary','left_temporal_boundary','right_temporal_boundary','donor_upper_boundary','donor_lower_boundary','donor_left_boundary','donor_right_boundary','crown_boundary') or p_smoothing_mode not in ('linear','catmull_rom') or jsonb_typeof(p_points)<>'array' then raise exception using errcode='22023',message='MODEL_CURVE_INVALID'; end if; n:=jsonb_array_length(p_points);
 if (p_curve_code='crown_boundary' and (not p_closed or n<4 or n>64)) or (p_curve_code<>'crown_boundary' and (p_closed or n<3 or n>64)) or (p_smoothing_mode='catmull_rom' and n<4) or exists(select 1 from jsonb_array_elements(p_points) x where jsonb_typeof(x)<>'object' or x->>'id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or x->>'order_index' !~ '^(0|[1-9][0-9]*)$' or x->>'x' !~ '^-?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$' or x->>'y' !~ '^-?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$' or x->>'z' !~ '^-?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$' or (x->>'x')::numeric not between -2 and 2 or (x->>'y')::numeric not between -2 and 2 or (x->>'z')::numeric not between -2 and 2) or (select count(distinct x->>'id') from jsonb_array_elements(p_points) x)<>n or (select count(distinct (x->>'order_index')::integer) from jsonb_array_elements(p_points) x)<>n or (select min((x->>'order_index')::integer) from jsonb_array_elements(p_points) x)<>0 or (select max((x->>'order_index')::integer) from jsonb_array_elements(p_points) x)<>n-1 then raise exception using errcode='22023',message='MODEL_CURVE_INVALID'; end if;
 h:=encode(extensions.digest(concat_ws(':',p_annotation_package_id,p_curve_code,p_points::text,p_closed,p_smoothing_mode,p_expected_package_revision,p_expected_pointer_revision),'sha256'),'hex'); select * into e from public.model_annotation_idempotency where clinic_id=p.clinic_id and actor_platform_user_id=c.actor_id and request_family='curve' and idempotency_key=p_idempotency_key; if found then if e.payload_hash<>h then raise exception using errcode='40001',message='MODEL_CURVE_IDEMPOTENCY_MISMATCH'; end if; return query select e.result_resource_id,e.result_revision,e.result_revision,false; return; end if;
 
