-- graftvision:dangerous-sql-reason Controlled row locks and revision updates serialize immutable Doctor annotation saves.
-- graftvision:corrective-plan Forward-fix through an additive migration; append-only annotation versions, pointers, events, and audit history remain preserved.
select * into q from public.model_annotation_curve_current where annotation_package_id=p.id and curve_code=p_curve_code for update; has_pointer:=found; if has_pointer and q.revision<>p_expected_pointer_revision then raise exception using errcode='40001',message='MODEL_CURVE_POINTER_CONFLICT'; end if; if not has_pointer and p_expected_pointer_revision<>0 then raise exception using errcode='40001',message='MODEL_CURVE_POINTER_CONFLICT'; end if;
 perform set_config('graftvision.scan_controlled','on',true); insert into public.model_annotation_curve_version(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,curve_code,control_points,closed,smoothing_mode,revision,supersedes_curve_id,created_by) values(p.id,p.clinic_id,p.patient_id,p.consultation_id,p.model_package_id,p.reconstruction_output_manifest_id,p.model_artifact_id,p.geometry_revision,p_curve_code,p_points,p_closed,p_smoothing_mode,p.revision+1,case when has_pointer then q.current_version_id else null end,c.actor_id) returning id into v;
 insert into public.model_annotation_curve_current(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,normalization_version,curve_code,current_version_id,prior_version_id,revision,updated_by) values(p.id,p.clinic_id,p.patient_id,p.consultation_id,p.model_package_id,p.reconstruction_output_manifest_id,p.model_artifact_id,p.geometry_revision,p.normalization_version,p_curve_code,v,case when has_pointer then q.current_version_id else null end,1,c.actor_id) 
-- graftvision:dangerous-sql-approved task=MODEL-001
-- graftvision:dangerous-sql-reason Controlled row locks and revision updates serialize immutable Doctor annotation saves.
-- graftvision:corrective-plan Forward-fix through an additive migration; append-only annotation versions, pointers, events, and audit history remain preserved.
on conflict(annotation_package_id,curve_code) do update set current_version_id=excluded.current_version_id,prior_version_id=model_annotation_curve_current.current_version_id,revision=model_annotation_curve_current.revision+1,updated_at=clock_timestamp(),updated_by=excluded.updated_by returning revision into pointer_revision;
 
-- graftvision:dangerous-sql-approved task=MODEL-001
-- graftvision:dangerous-sql-reason Controlled row locks and revision updates serialize immutable Doctor annotation saves.
-- graftvision:corrective-plan Forward-fix through an additive migration; append-only annotation versions, pointers, events, and audit history remain preserved.
update public.model_annotation_package set revision=revision+1 where id=p.id returning revision into package_revision; insert into public.model_annotation_event(annotation_package_id,clinic_id,event_type,actor_platform_user_id,annotation_reference_id,annotation_code,revision) values(p.id,p.clinic_id,'curve_saved',c.actor_id,v,p_curve_code,package_revision); insert into public.audit_event(audit_scope,clinic_id,actor_platform_user_id,actor_type,action,resource_type,resource_id,outcome,request_id,source_application,metadata) values('clinic',p.clinic_id,c.actor_id,'user','model.curve_saved','consultation',p.consultation_id,'success',p_idempotency_key,'web',jsonb_build_object('annotation_package_id',p.id,'model_package_id',p.model_package_id,'annotation_kind','curve','annotation_code',p_curve_code,'revision',package_revision,'package_state','draft','geometry_revision',p.geometry_revision)); insert into public.model_annotation_idempotency(clinic_id,actor_platform_user_id,request_family,idempotency_key,payload_hash,result_resource_id,result_status,result_revision) values(p.clinic_id,c.actor_id,'curve',p_idempotency_key,h,v,'created',package_revision); return query select v,package_revision,pointer_revision,true; end; $$;
revoke all on function graftvision_private.save_model_curve(uuid,uuid,uuid,text,jsonb,boolean,text,integer,integer,uuid) from public,anon,authenticated;
